  'maintaining-heading' => 'Հետևողական ձևաչափերի պահպանում',
  'maintaining-p1' => 'Ստեղծեք պարզ ստանդարտ ձեր թիմի համար: Օրինակ, սևագրերը մնում են Word-ում, վերջնական տարբերակները թողարկվում են PDF ձևաչափով, իսկ տեսողական ակտիվները համօգտագործվում են որպես JPG: Հստակ կանոնը նվազեցնում է շփոթությունը, հատկապես, երբ մի քանի մարդ աշխատում է նույն նախագծի վրա:',
  'maintaining-p2' => 'Պահպանեք հիմնական ֆայլերը կանխատեսելի թղթապանակի կառուցվածքում՝ ֆայլերի անուններում տարբերակների համարներով: Սա հեշտացնում է հետագայում ճիշտ ձևաչափը գտնելը, անկախ նրանից՝ ձեզ անհրաժեշտ է խմբագրվող աղբյուրը, թե վերջնական ֆիքսված տարբերակը:',
  'faq-heading' => 'Հաճախակի տրվող հարցեր',
  'faq1-q' => 'Ո՞ր ձևաչափն է լավագույնը հաճախորդների հետ փաստաթուղթը կիսելու համար:',
  'faq1-a' => 'PDF-ը սովորաբար լավագույնն է, քանի որ այն պահպանում է դասավորությունը հետևողական և խանգարում է չնախատեսված խմբագրումներին: Համօգտագործեք Word-ի տարբերակը միայն այն դեպքում, երբ հաճախորդը պետք է վերանայի տեքստը:',
  'faq2-q' => 'Կարո՞ղ եմ JPG-ը նորից վերածել Word-ի:',
  'faq2-a' => 'Ոչ ուղղակիորեն օգտակար ձևով: JPG-ն նկար է, ուստի նախ ձեզ հարկավոր է տեքստի ճանաչում, և արդյունքը կարող է զգալի մաքրման կարիք ունենալ: Հնարավորության դեպքում պահեք բնօրինակ Word ֆայլը:',
  'faq3-q' => 'Արդյո՞ք Word ֆայլը PDF-ի վերածելը որևէ տեղեկություն կորցնում է:',
  'faq3-a' => 'Սովորաբար ոչ, բայց որոշ առանձնահատկություններ, ինչպիսիք են որոշ ինտերակտիվ տարրեր կամ մեկնաբանություններ, կարող են չփոխանցվել: Ուղարկելուց առաջ ուշադիր ստուգեք PDF-ը:',
  'faq4-q' => 'Արդյո՞ք PDF-ը միշտ ավելի լավն է, քան Word-ը վերջնական փաստաթղթերի համար:',
  'faq4-a' => 'Վերջնական փաստաթղթերի համար, որոնք չպետք է փոխվեն, այո: Փաստաթղթերի համար, որոնք կշարունակեն զարգանալ, պահեք Word տարբերակը որպես աշխատանքային ֆայլ:',
  'faq5-q' => 'Ո՞ր ձևաչափն է օգտագործում ամենաքիչ պահեստը:',
  'faq5-a' => 'Դա կախված է բովանդակությունից: JPG-ն կարող է փոքր լինել պարզ էջի համար, մինչդեռ ներկառուցված տառատեսակներով և պատկերներով PDF-ը կարող է ավելի մեծ լինել: Ֆայլը ձեր օգտագործած ձևաչափով սեղմելը հաճախ չափը նվազեցնելու ամենաարդյունավետ միջոցն է:',
);
